package com.mineocclude.server;

import org.junit.jupiter.api.Test;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Cross-language check (C2.4): a schedule generated by the real Python
 * producer (``mineocclude.data.noise_schedule``, NumPy PCG64, seed 777,
 * n_draws 20, q 0.2) must load and yield the exact draws Python computed.
 *
 * The resource file was generated by the pinned producer and committed; its
 * expected values below were printed by the same Python run. Regenerating the
 * resource without updating these constants (or vice versa) fails the test.
 */
class PythonScheduleCrossCheckTest {

    @Test
    void pythonProducedScheduleLoadsExactly() throws Exception {
        Path tmp = Files.createTempFile("python_schedule", ".jsonl");
        try (java.io.InputStream in =
                     getClass().getResourceAsStream("/python_schedule_seed777.jsonl")) {
            Files.copy(in, tmp, StandardCopyOption.REPLACE_EXISTING);
        }
        NoiseSchedule schedule = NoiseSchedule.load(tmp, 777);
        assertEquals(20, schedule.size());
        assertEquals(0.2, schedule.q, 0.0);
        assertEquals(0.05, schedule.dtSeconds, 0.0);
        // Exact draws printed by the Python producer run.
        assertEquals(-0.08475155145647387, schedule.nextNoiseDraw(), 0.0);
        for (int i = 1; i < 19; i++) {
            schedule.nextNoiseDraw();
        }
        assertEquals(0.03793659490551743, schedule.nextNoiseDraw(), 0.0);
        assertEquals(0, schedule.remaining());
        Files.deleteIfExists(tmp);
    }
}
